//! Swift and Kotlin bindings for `gage-core`, generated by UniFFI
//! ([ADR-0060]). A frontend like `gage-cli`: it adapts the library's types
//! for a foreign caller and holds no behavior of its own.
//!
//! The library never depends on UniFFI, so every type that crosses the
//! boundary is wrapped or mirrored here rather than annotated there.
//!
//! [ADR-0060]: https://github.com/distillerylabs/gage-rs/blob/main/doc/decisions/0060-mobile-bindings.md

use std::fmt::Display;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use gage::entry::{CandidateList, Timestamp};
use gage::prompter::{self as core_prompter, Kind, Purpose};
use gage::storage::xdgpaths::Dirs;
use gage::storage::{config, paths};
use gage::{ErrorKind, HasKind};
use uuid::Uuid;
use zeroize::Zeroizing;

uniffi::setup_scaffolding!();

/// Where gage keeps its config, identities and state. A mobile app has no
/// XDG directories, so it names three directories inside its own container.
#[derive(Debug, Clone, uniffi::Record)]
pub struct Roots {
    pub config: String,
    pub data: String,
    pub state: String,
}

impl Roots {
    fn dirs(&self) -> Dirs {
        Dirs {
            config: PathBuf::from(&self.config),
            data: PathBuf::from(&self.data),
            state: PathBuf::from(&self.state),
        }
    }
}

/// Every failure, keyed by the library's [`ErrorKind`] and carrying its
/// message unchanged (ADR-0054).
#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum GageError {
    #[error("{message}")]
    Conflict { message: String },
    #[error("{message}")]
    Usage { message: String },
    #[error("{message}")]
    NotFound { message: String },
    #[error("{message}")]
    Ambiguous { message: String },
    #[error("{message}")]
    LockedOrAuth { message: String },
    #[error("{message}")]
    Internal { message: String },
    #[error("{message}")]
    Unreachable { message: String },
}

impl GageError {
    fn new(kind: ErrorKind, message: String) -> GageError {
        match kind {
            ErrorKind::Conflict => GageError::Conflict { message },
            ErrorKind::Usage => GageError::Usage { message },
            ErrorKind::NotFound => GageError::NotFound { message },
            ErrorKind::Ambiguous => GageError::Ambiguous { message },
            ErrorKind::LockedOrAuth => GageError::LockedOrAuth { message },
            ErrorKind::Internal => GageError::Internal { message },
            ErrorKind::Unreachable => GageError::Unreachable { message },
        }
    }

    fn from_core<E: HasKind + Display>(e: E) -> GageError {
        GageError::new(e.kind(), e.to_string())
    }
}

/// The identity method an [`UnlockRequest`] asks about.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum UnlockKind {
    Passphrase,
}

/// Whether an [`UnlockRequest`] opens an existing identity or protects a
/// new one.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum UnlockPurpose {
    Unlock,
    Create,
}

/// What the library needs a person to answer to unlock a vault. `attempt`
/// counts from 1; the retry policy is the app's.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct UnlockRequest {
    pub kind: UnlockKind,
    pub purpose: UnlockPurpose,
    pub vault: String,
    pub device: String,
    pub attempt: u32,
}

/// The app's answer to an [`UnlockRequest`].
#[derive(uniffi::Enum)]
pub enum UnlockResponse {
    Passphrase { passphrase: String },
}

/// Why the app produced no answer.
#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum PromptError {
    /// The person declined to answer.
    #[error("cancelled")]
    Cancelled,
    /// The app's retry policy ended the unlock.
    #[error("too many incorrect passphrase attempts")]
    TooManyAttempts,
    /// The app could not ask.
    #[error("{message}")]
    Failed { message: String },
}

impl From<uniffi::UnexpectedUniFFICallbackError> for PromptError {
    fn from(e: uniffi::UnexpectedUniFFICallbackError) -> PromptError {
        PromptError::Failed { message: e.reason }
    }
}

/// A non-fatal advisory to show once.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct Warning {
    pub text: String,
}

/// The human decisions an unlock needs, implemented by the app.
#[uniffi::export(with_foreign)]
pub trait Prompter: Send + Sync {
    fn unlock(&self, request: UnlockRequest) -> Result<UnlockResponse, PromptError>;

    fn warn(&self, warning: Warning);
}

/// The library's `Prompter`, answered by the app's.
struct Bridge<'a>(&'a dyn Prompter);

impl core_prompter::Prompter for Bridge<'_> {
    fn unlock(
        &self,
        req: &core_prompter::UnlockRequest,
    ) -> Result<core_prompter::UnlockResponse, core_prompter::PromptError> {
        let kind = match req.kind {
            Kind::Passphrase => UnlockKind::Passphrase,
            other => {
                return Err(core_prompter::PromptError::UnsupportedKind(format!(
                    "{other:?}"
                )));
            }
        };
        let purpose = match req.purpose {
            Purpose::Unlock => UnlockPurpose::Unlock,
            Purpose::Create => UnlockPurpose::Create,
        };
        let answer = self.0.unlock(UnlockRequest {
            kind,
            purpose,
            vault: req.vault.clone(),
            device: req.device.clone(),
            attempt: req.attempt,
        });
        match answer {
            Ok(UnlockResponse::Passphrase { passphrase }) => {
                // The foreign copy is beyond reach; this one is wiped.
                let passphrase = Zeroizing::new(passphrase);
                Ok(core_prompter::UnlockResponse::passphrase(
                    passphrase.as_str(),
                ))
            }
            Err(PromptError::Cancelled) => Err(core_prompter::PromptError::Cancelled),
            Err(PromptError::TooManyAttempts) => Err(core_prompter::PromptError::TooManyAttempts),
            Err(PromptError::Failed { message }) => Err(core_prompter::PromptError::Io(
                std::io::Error::other(message),
            )),
        }
    }

    // The questions below aren't exposed yet; nothing the bindings call
    // asks them, and one that did is refused rather than answered.

    fn confirm(&self, _: &str) -> Result<bool, core_prompter::PromptError> {
        Err(core_prompter::PromptError::NotInteractive)
    }

    fn confirm_default_yes(&self, _: &str) -> Result<bool, core_prompter::PromptError> {
        Err(core_prompter::PromptError::NotInteractive)
    }

    fn value(&self, _: &str) -> Result<Zeroizing<String>, core_prompter::PromptError> {
        Err(core_prompter::PromptError::NotInteractive)
    }

    fn choose(&self, _: &CandidateList) -> Result<Uuid, core_prompter::PromptError> {
        Err(core_prompter::PromptError::NotInteractive)
    }

    fn warn(&self, warning: &core_prompter::Warning) {
        self.0.warn(Warning {
            text: warning.text.clone(),
        });
    }
}

/// An unlocked identity. The app holds a handle and never the key; the key
/// is wiped and its page lock released when the last handle is released.
/// On Kotlin that means calling `close()` (ADR-0060).
#[derive(Debug, uniffi::Object)]
pub struct Identity {
    inner: gage::Identity,
}

/// One entry's listing row. Values and fields stay encrypted.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct ListEntry {
    pub id: String,
    pub title: String,
    pub description: String,
    pub created: Option<SystemTime>,
    pub updated: Option<SystemTime>,
    pub updated_by: String,
}

fn system_time(t: Timestamp) -> SystemTime {
    let secs = t.as_unix();
    let offset = Duration::from_secs(secs.unsigned_abs());
    if secs >= 0 {
        UNIX_EPOCH + offset
    } else {
        UNIX_EPOCH - offset
    }
}

/// One registered vault.
#[derive(Debug, uniffi::Object)]
pub struct Vault {
    inner: gage::Vault,
}

#[uniffi::export]
impl Vault {
    /// The vault registered as `name` under `roots`.
    #[uniffi::constructor]
    pub fn open(roots: Roots, name: String) -> Result<Arc<Vault>, GageError> {
        let dirs = roots.dirs();
        let global = config::load_or_default(&paths::global_config_file(&dirs))
            .map_err(GageError::from_core)?;
        let entry = global.entry(&name).map_err(GageError::from_core)?;
        let inner =
            gage::Vault::from_registration(&dirs, &name, entry).map_err(GageError::from_core)?;
        Ok(Arc::new(Vault { inner }))
    }

    /// Unlocks this device's identity, asking `prompter` for as many tries
    /// as it is willing to answer.
    pub fn unlock(&self, prompter: Arc<dyn Prompter>) -> Result<Arc<Identity>, GageError> {
        let inner = self
            .inner
            .unlock(&Bridge(prompter.as_ref()))
            .map_err(GageError::from_core)?;
        Ok(Arc::new(Identity { inner }))
    }

    /// Every entry's listing row, sorted by title then id.
    pub fn list(&self, identity: Arc<Identity>) -> Result<Vec<ListEntry>, GageError> {
        let rows = self
            .inner
            .list(&identity.inner)
            .map_err(GageError::from_core)?;
        Ok(rows
            .into_iter()
            .map(|r| ListEntry {
                id: r.id.hyphenated().to_string(),
                title: r.title,
                description: r.description,
                created: r.created.map(system_time),
                updated: r.updated.map(system_time),
                updated_by: r.updated_by,
            })
            .collect())
    }
}

